def shortest_subarray_or_at_least_k(nums,k):
    best=len(nums)+1
    for left in range(len(nums)):
        value=0
        for right in range(left,len(nums)):
            value|=nums[right]
            if value>=k:best=min(best,right-left+1);break
    return -1 if best>len(nums) else best

